    /* 확인 */
    onButtonTapSave: function(button, e, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var vm = me.getViewModel();
        var grid = refs.hrHromJasPrjGrid;
        var frmDetail = refs.frmDetail;


        //신규인 경우에만 아래와 같이 유효성 검증
        if(Constants.crudState.CREATE == vm.get('crud')){ //알림기본ID가 비어있는
            if (Ext.isEmpty(grid.getStore())) {
                Ext.Msg.alert('유효성 검증', '대상자를 지정해주세요.');
                return false;
            }
        }

        var errMsg = me.validationCheck();
        if(!Ext.isEmpty(errMsg)){
            Ext.Msg.alert('유효성 검증', errMsg);
            return false;
        }
        //END 유효성 검증 AREA


        var values = vm.get('record');
        values.title = vm.get('record.title');
        values.trsNm = vm.get('record.title');
        values.body = vm.get('record.body');
        values.priority = vm.get('record.priority');

        values.content = vm.get('record.content');
        values.content = values.content.replace(/\n/g,'<br/>');



        if(Constants.crudState.CREATE == vm.get('crud')){
            values.tasTrsDvcd = '60';  // PUSH Code
            values.boTasmLemeId = '1'; // 알림기본(PUSH)
            values.msgDvcd = '01'; // 메시지구분 - 공지
            values.fmtDvcd = '01'; // 서식구분 - 텍스트 + 이미지
            values.msgChkActDvcd = '01'; // 메시지확인 액션구분 - 일반
        }
        else{
            values.tasTrsDvcd = vm.get('selectedRecord.tasTrsDvcd');
        }


        var data = {
            record : values,
            gridData : vm.get('hrHromJasPrjStore'),
        };
        Ext.Ajax.request({
            headers: {
                viewId : me.getViewId(),
                serviceId : 'BomTasSvc.saveBomTasTrs'
            },
            jsonData : data,
            scope : me,
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);

                Ext.Msg.alert('안내', Messages.getMessage('I0000'));
                me.getView().up().down('BomTasSend01M').controller.onSelect();
                vm.getView().up().pop();

            }
        });
    },

